sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.ch-features {
  width: 100%;
  box-sizing: border-box;
  padding: 56px 0 8px;
  background: #faf6ef;
  font-family: 'Inter', system-ui, -apple-system, 'Segoe UI', Arial, sans-serif;
  font-size: 15px;
  line-height: 1.6;
}
.ch-features *, .ch-features *::before, .ch-features *::after { box-sizing: border-box; }

.ch-features-container { width: 92%; max-width: 1120px; margin: 0 auto; }

.ch-features-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}

.ch-feature {
  text-align: center;
  padding: 0 14px;
  border-right: 1px solid #e7e1d4;
}
.ch-feature:last-child { border-right: none; }

.ch-feature-icon {
  margin-bottom: 8px;
  color: #d4b07c;
  font-size: 1.6rem;
  line-height: 1.3;
}

.ch-feature h3 {
  margin: 0 0 4px;
  font-family: inherit;
  font-size: 1.05rem;
  font-weight: 600;
  letter-spacing: .08em;
  line-height: 1.3;
  text-transform: uppercase;
  color: #1f3a30;
}

.ch-feature p {
  margin: 0;
  color: #6f756f;
  font-size: .85rem;
  line-height: 1.6;
}

@media (max-width: 900px) {
  .ch-features-grid { grid-template-columns: repeat(2, 1fr); row-gap: 32px; }
  .ch-feature:nth-child(2) { border-right: none; }
}

@media (max-width: 520px) {
  .ch-features-grid { grid-template-columns: 1fr; }
  .ch-feature { border-right: none; }
}
